    public virtual void handleTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "topic": "publicTrade.BTCUSDT",
        //         "type": "snapshot",
        //         "ts": 1672304486868,
        //         "data": [
        //             {
        //                 "T": 1672304486865,
        //                 "s": "BTCUSDT",
        //                 "S": "Buy",
        //                 "v": "0.001",
        //                 "p": "16578.50",
        //                 "L": "PlusTick",
        //                 "i": "20f43950-d8dd-5b31-9112-a178eb6023af",
        //                 "BT": false
        //             }
        //         ]
        //     }
        //
        object data = this.safeValue(message, "data", new Dictionary<string, object>() {});
        string? topic = this.safeString(message, "topic", "");
        object trades = data;
        List<object> parts = topic.Split(new [] {"."}, StringSplitOptions.None).ToList<object>();
        bool isSpot = ((string)client.url).IndexOf("spot", StringComparison.Ordinal) >= 0;
        string marketType = "contract";
        if (isSpot)
        {
            marketType = "spot";
        }
        string? marketId = this.safeString(parts, 1);
        Dictionary<string, object> market = this.safeMarket(marketId, null, null, marketType);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        ccxt.pro.ArrayCache stored = ((ccxt.pro.ArrayCache)this.safeValue(this.trades, symbol));
        if ((stored == null))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            stored = new ArrayCache(limit);
            this.trades[(string)symbol] = stored;
        }
        for (int j = 0; j < getArrayLength(trades); j++)
        {
            Dictionary<string, object> parsed = this.parseWsTrade(getValue(trades, j), market);
            stored.append(parsed);
        }
        string messageHash = (("trade" + ":") + symbol);
        client.resolve(stored, messageHash);
    }

    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        // public
        //    {
        //         "T": 1672304486865,
        //         "s": "BTCUSDT",
        //         "S": "Buy",
        //         "v": "0.001",
        //         "p": "16578.50",
        //         "L": "PlusTick",
        //         "i": "20f43950-d8dd-5b31-9112-a178eb6023af",
        //         "BT": false
        //     }
        //
        // spot private
        //     {
        //         "e": "ticketInfo",
        //         "E": "1662348310386",
        //         "s": "BTCUSDT",
        //         "q": "0.001007",
        //         "t": "1662348310373",
        //         "p": "19842.02",
        //         "T": "2100000000002220938",
        //         "o": "1238261807653647872",
        //         "c": "spotx008",
        //         "O": "1238225004531834368",
        //         "a": "533287",
        //         "A": "642908",
        //         "m": false,
        //         "S": "BUY"
        //     }
        //
        string? id = this.safeStringN(trade, new List<object>() {"i", "T", "v"});
        bool isContract = ((trade != null && ((IDictionary<string, object>)trade).ContainsKey("BT")));
        object marketType = "spot";
        if (isContract)
        {
            marketType = "contract";
        }
        if ((market != null))
        {
            marketType = getValue(market, "type");
        }
        string? marketId = this.safeString(trade, "s");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, null, marketType);
        string? symbol = ((string)(marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null));
        Int64? timestamp = this.safeInteger2(trade, "t", "T");
        string? side = this.safeStringLower(trade, "S");
        object takerOrMaker = null;
        object m = this.safeValue(trade, "m");
        if ((side == null))
        {
            side = (isEqual(m, true)) ? "buy" : "sell";
        } else
        {
            // spot private
            takerOrMaker = m;
        }
        string? price = this.safeString(trade, "p");
        string? amount = this.safeString2(trade, "q", "v");
        string? orderId = this.safeString(trade, "o");
        return this.safeTrade(new Dictionary<string, object>() {
            { "id", id },
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "order", orderId },
            { "type", null },
            { "side", side },
            { "takerOrMaker", takerOrMaker },
            { "price", price },
            { "amount", amount },
            { "cost", null },
            { "fee", null },
        }, marketResolved);
    }

    public virtual string getPrivateType(object url)
    {
        if (((string)url).IndexOf("spot", StringComparison.Ordinal) >= 0)
        {
            return "spot";
        } else if (((string)url).IndexOf("v5/private", StringComparison.Ordinal) >= 0)
        {
            return "unified";
        } else
        {
            return "usdc";
        }
    }

